pages['historia']=nav('historia')+'''<main><section class="pagetitle"><span class="eyebrow">02 / MINHA HISTÓRIA</span><h1>Prazer,<br><em>Igor Franco.</em></h1><div class="aboutlead"><p>Sou desenvolvedor Full Stack. Minha trajetória reúne trabalho freelance, produtos de equipes e a construção de um SaaS autoral.</p><div class="signature">IF<span>WEB / MOBILE / BACK-END</span></div></div></section><section class="introstrip"><span class="eyebrow">O FIO CONDUTOR</span><div><h2>Aprender construindo.<br><em>E acompanhar a entrega.</em></h2><p>Atuo com desenvolvimento web freelance desde 2023, ano em que concluí Análise e Desenvolvimento de Sistemas na Unopar. Na Thux/Mathux, trabalhei em aplicações web, mobile e back-end, assumindo entregas mobile até o lançamento.</p><p>Hoje, meu percurso também passa pela Mágicos da Limpeza e pelo Escoply, uma plataforma autoral para gestão freelance em construção e em testes com usuários convidados.</p></div></section><section class="timeline"><div class="sectionhead"><span class="eyebrow">PERCURSO / 2023 — 2026</span></div>'''+''.join(f'<div class="timelineitem"><span class="eyebrow">{date}</span><div><h3>{title}</h3><p>{body}</p></div></div>' for date,title,body in [('2023','Formação e trabalho freelance','Conclusão do tecnólogo em Análise e Desenvolvimento de Sistemas na Unopar. Desenvolvimento web freelance desde 2023.'),('JUN 2025 — AGO 2026','Thux / Mathux','Produtos web e mobile, integrações, testes e lançamentos em produção.'),('JAN 2026 — ATUAL','Mágicos da Limpeza','Desenvolvimento Full Stack em colaboração, conectando web, mobile e back-end.'),('EM CONSTRUÇÃO','Escoply','SaaS autoral para freelancers. Testes com usuários convidados e evolução de recursos com IA.')])+'''</section><section class="introstrip"><span class="eyebrow">FERRAMENTAS DE TRABALHO</span><div class="expertise"><h3>Interfaces</h3><p>React, Next.js, TypeScript, HTML, CSS, SCSS e Tailwind CSS.</p><h3>Mobile</h3><p>React Native, Expo, recursos nativos e publicação nas lojas.</p><h3>Back-end e dados</h3><p>Node.js, NestJS, Express, Fastify, Supabase, PostgreSQL, MySQL e NoSQL. Java e Spring Boot.</p><h3>Entrega e qualidade</h3><p>Git, GitHub, AWS, testes unitários e E2E, CI/CD, Scrum e Kanban.</p><h3>Formação complementar</h3><p>StarSe Executive Education · Vai Na Web · Alura.</p></div></section><section class="contactstrip"><h2>Continuamos a conversa?</h2>'''+go('contato','Fale comigo '+icon('arrow-up-right'),'button')+'</section></main>'+foot()
