innerjs='''function filterProjects(button,category){document.querySelectorAll('.filter').forEach(b=>{b.classList.remove('chosen');b.setAttribute('aria-pressed','false')});button.classList.add('chosen');button.setAttribute('aria-pressed','true');document.querySelectorAll('[data-category]').forEach(a=>a.hidden=category!=='all'&&a.dataset.category!==category)}async function copyEmail(button){try{await navigator.clipboard.writeText('igorviniciusf10@gmail.com');document.getElementById('copystatus').textContent='Endereço copiado.'}catch(e){document.getElementById('copystatus').textContent='Não foi possível copiar. Selecione o endereço acima.'}}'''
options=[('inicio','01 · Início'),('projetos','02 · Projetos'),('escoply','03 · Escoply'),('magicos','04 · Mágicos da Limpeza'),('thux','05 · Thux / Mathux'),('historia','06 · Minha história'),('contato','07 · Contato'),('sistema','08 · Guia visual e ícones')]
html='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Design — Igor Franco</title><style>*{box-sizing:border-box}body{margin:0;background:#d6d2c9;font:13px Arial,sans-serif;color:#14201f}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:14px 22px;flex-wrap:wrap;border-bottom:1px solid #aaa99f}.toolbar strong{font-size:15px}.toolbar span{font-size:11px}.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}select,.controls button{font:12px Arial;padding:10px;border:1px solid #7f867d;background:transparent;color:#14201f;min-height:40px}.controls button{cursor:pointer}.controls button[aria-pressed=true]{background:#14201f;color:#eee9dd}.stage{padding:24px;display:flex;justify-content:center}iframe{width:1200px;max-width:100%;height:calc(100vh - 125px);min-height:600px;border:0;background:#14201f;box-shadow:0 8px 28px #0002;transition:width .2s}body.mobile iframe{width:390px}.hint{font-size:11px;color:#4c5650;padding:0 24px 12px;text-align:center}a{color:inherit}@media(max-width:600px){.stage{padding:12px 0}iframe{height:80vh}.toolbar{padding:12px;gap:10px}.toolbar span{display:none}}@media(prefers-reduced-motion:reduce){iframe{transition:none}}</style></head><body><div class="toolbar"><div><strong>design / Igor Franco</strong> <span>— Caderno visual · proposta 01</span></div><div class="controls"><label for="screen">Tela</label><select id="screen" onchange="show(this.value)">'''+''.join(f'<option value="{k}">{v}</option>' for k,v in options)+'''</select><button id="desktop" aria-pressed="true" onclick="mode(false)">Desktop</button><button id="mobile" aria-pressed="false" onclick="mode(true)">Celular · 390</button></div></div><div class="stage"><iframe id="preview" title="Prévia do portfólio de Igor Franco"></iframe></div><div class="hint">Navegue pelas telas e alterne o formato. Role dentro da prévia para ver o restante. · <a href="design.md">Especificação escrita</a></div><script>'''+ 'const pages='+json.dumps(pages,ensure_ascii=False)+';const css='+json.dumps(css)+';const defs='+json.dumps(defs)+';const innerjs='+json.dumps(innerjs)+''';function show(key){document.getElementById('screen').value=key;document.getElementById('preview').srcdoc='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>'+css+'</style></head><body>'+defs+pages[key]+'<script>'+innerjs+'<\/script></body></html>'}function mode(mobile){document.body.classList.toggle('mobile',mobile);document.getElementById('mobile').setAttribute('aria-pressed',String(mobile));document.getElementById('desktop').setAttribute('aria-pressed',String(!mobile))}show('inicio');</script></body></html>'''
(out/'design.html').write_text(html,encoding='utf-8')
iconfolder=out/'icons';iconfolder.mkdir(exist_ok=True)
for name,body in icons.items():
 (iconfolder/(name+'.svg')).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">{body}</svg>',encoding='utf-8')
print('Design visual criado: 8 telas, versões desktop/mobile e 12 ícones SVG.')

